WITH exploded AS (SELECT id, plan, effective_from, val FROM price_tiers LATERAL VIEW EXPLODE(tier_prices) e AS val) SELECT *, DENSE_RANK() OVER (ORDER BY val DESC) val_dense_rank, DENSE_RANK() OVER (PARTITION BY plan ORDER BY val ASC NULLS LAST) val_dense_rank_2, STDDEV_SAMP(val) OVER (PARTITION BY plan) plan_stddev_samp_val, DENSE_RANK() OVER (ORDER BY val DESC NULLS LAST) val_dense_rank_3, SUM(val) OVER (PARTITION BY plan) plan_sum_val FROM exploded;
